const items = $input.all();
const claudeResponse = items[0].json;
const textContent = (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) || '';

let parsed;
try {
  const jsonMatch = textContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  parsed = {
    reply: textContent || 'Désolée, je n\'ai pas compris. Pouvez-vous reformuler ?',
    buttons: [
      { label: '🍛 Voir la carte', value: 'voir_carte' },
      { label: '💬 Parler à l\'équipe', value: 'commander_whatsapp' }
    ],
    signal: 'cold'
  };
}

const webhookData = $('Webhook Vanessa Chat').first().json;
parsed.sessionId = (webhookData.body && webhookData.body.sessionId) || 'unknown';
parsed.usage = {
  input_tokens: (claudeResponse.usage && claudeResponse.usage.input_tokens) || 0,
  output_tokens: (claudeResponse.usage && claudeResponse.usage.output_tokens) || 0
};

return [{ json: parsed }];

const webhookData = $('Webhook Vanessa Chat').first().json;
const body = (webhookData && webhookData.body) || {};
const parsed = $('Parse Claude Response').first().json;

const event = {
  timestamp: new Date().toISOString(),
  sessionId: body.sessionId || 'unknown',
  userMessage: body.message || '',
  botReply: parsed.reply || '',
  signal: parsed.signal || 'cold',
  buttons: parsed.buttons || [],
  page: body.page || '/',
  inputTokens: (parsed.usage && parsed.usage.input_tokens) || 0,
  outputTokens: (parsed.usage && parsed.usage.output_tokens) || 0
};

return [{ json: event }];
